// spelling-bee/js/engine.js - the rules of Spelling Bee, pure (no DOM, no storage).
// Data: spelling-bee/data/bee.json, GENERATED by tools/build-spelling-bee-data.mjs.
//
// The NYT rules: words of 4+ letters, every word uses the centre letter, letters can repeat.
// A 4-letter word scores 1, a longer word one point per letter, a pangram (all seven letters)
// 7 more. Ranks are a share of the puzzle's total points (RANKS below).

export const RANKS = [
  { id: 'beginner', pct: 0 },
  { id: 'good_start', pct: 2 },
  { id: 'moving_up', pct: 5 },
  { id: 'good', pct: 8 },
  { id: 'solid', pct: 15 },
  { id: 'nice', pct: 25 },
  { id: 'great', pct: 40 },
  { id: 'amazing', pct: 50 },
  { id: 'genius', pct: 70 },
  { id: 'queen_bee', pct: 100 },
];
export const GENIUS = 8;   // index of Genius in RANKS
export const QUEEN = 9;
export const MAX_LEN = 19; // longer input is refused ("Too long")

const DATA_URL = new URL('../data/bee.json', import.meta.url);

/** Parse the generated file into { epoch, words: string[], extra: string[], puzzles: string[] }.
 *  `words` are the answers (hints and ranks count them); `extra` are rarer real words, accepted and
 *  scored as bonus words but never counted (Matt, 2026-10-26: "all words should count"). */
export function parseData(raw) {
  if (!raw || typeof raw.words !== 'string' || !Array.isArray(raw.puzzles) || !raw.puzzles.length) throw new Error('bad bee data');
  const extra = typeof raw.extra === 'string' && raw.extra ? raw.extra.split(' ') : [];
  // retired: day -> the letters that day had before it was swapped for a fuller puzzle.
  const retired = raw.retired && typeof raw.retired === 'object' ? raw.retired : {};
  return { epoch: raw.epoch, words: raw.words.split(' '), extra, puzzles: raw.puzzles, retired };
}

export async function loadData() {
  const res = await fetch(DATA_URL);
  if (!res.ok) throw new Error('HTTP ' + res.status);
  return parseData(await res.json());
}

/** 'YYYY-MM-DD' for a Date, in LOCAL time (everyone's day turns over at their own midnight). */
export function dayKey(d) {
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

/** Whole days from `epoch` ('YYYY-MM-DD') to the local date `d`. */
export function dayNumber(epoch, d) {
  const [y, m, dd] = epoch.split('-').map(Number);
  const a = Date.UTC(y, m - 1, dd);
  const b = Date.UTC(d.getFullYear(), d.getMonth(), d.getDate());
  return Math.round((b - a) / 86400000);
}

/** The local Date of day n (noon, so DST never moves it to another day). */
export function dateOfDay(epoch, n) {
  const [y, m, dd] = epoch.split('-').map(Number);
  return new Date(y, m - 1, dd + n, 12);
}

/** Puzzle for day n: { center, outer: [6], letters: Set, key }. */
export function puzzleAt(data, n) {
  const len = data.puzzles.length;
  return puzzleOf(data.puzzles[((n % len) + len) % len]);
}

/** Puzzle from its letters 'c:abcdef'. */
export function puzzleOf(s) {
  const center = s[0];
  const outer = s.slice(2).split('');
  return { center, outer, letters: new Set([center, ...outer]), key: s };
}

export function isPangram(word, puzzle) {
  for (const c of puzzle.letters) if (!word.includes(c)) return false;
  return true;
}

export function scoreWord(word, puzzle) {
  return (word.length === 4 ? 1 : word.length) + (isPangram(word, puzzle) ? 7 : 0);
}

/** Every answer for the puzzle, alphabetical. */
export function answersFor(data, puzzle) {
  return fits(data.words, puzzle);
}

/** The bonus words for the puzzle: real words outside the answer list, alphabetical. */
export function extrasFor(data, puzzle) {
  return fits(data.extra || [], puzzle);
}

function fits(list, puzzle) {
  const out = [];
  for (const w of list) {
    if (!w.includes(puzzle.center)) continue;
    let ok = true;
    for (let i = 0; i < w.length; i++) if (!puzzle.letters.has(w[i])) { ok = false; break; }
    if (ok) out.push(w);
  }
  return out;
}

export function totalPoints(answers, puzzle) {
  let n = 0;
  for (const w of answers) n += scoreWord(w, puzzle);
  return n;
}

/** Minimum score for each rank (NYT rounds). */
export function rankThresholds(max) {
  return RANKS.map((r) => (r.pct === 100 ? max : Math.round((r.pct / 100) * max)));
}

/** Bonus words add points, so the score can pass `max` early: Queen Bee needs every answer (`all`). */
export function rankIndex(score, max, all = true) {
  const th = rankThresholds(max);
  let i = 0;
  for (let k = 0; k < th.length; k++) if (score >= th[k]) i = k;
  return i === QUEEN && !all ? GENIUS : i;
}

/** Why a typed word is refused, or null if it is a new answer or bonus word. Order matches the NYT game. */
export function checkWord(word, puzzle, answerSet, found, extraSet) {
  if (word.length < 4) return 'too_short';
  if (word.length > MAX_LEN) return 'too_long';
  for (const c of word) if (!puzzle.letters.has(c)) return 'bad_letters';
  if (!word.includes(puzzle.center)) return 'missing_center';
  if (!answerSet.has(word) && !(extraSet && extraSet.has(word))) return 'not_in_list';
  if (found.has(word)) return 'already_found';
  return null;
}

/** Praise for a found word: Good! / Nice! / Awesome! / Pangram! */
export function praiseFor(word, puzzle) {
  if (isPangram(word, puzzle)) return 'pangram';
  if (word.length === 4) return 'good';
  if (word.length <= 6) return 'nice';
  return 'awesome';
}

/** What is still left to find: the letter x length grid and the two-letter starts. */
export function hintsFor(answers, found, puzzle) {
  const left = answers.filter((w) => !found.has(w));
  const firsts = [...puzzle.letters].sort();
  const lens = [...new Set(answers.map((w) => w.length))].sort((a, b) => a - b);
  const grid = {};
  for (const f of firsts) { grid[f] = {}; for (const l of lens) grid[f][l] = 0; }
  const two = {};
  for (const w of left) {
    grid[w[0]][w.length] += 1;
    const k = w.slice(0, 2);
    two[k] = (two[k] || 0) + 1;
  }
  const pangrams = answers.filter((w) => isPangram(w, puzzle));
  return {
    words: left.length,
    points: totalPoints(left, puzzle),
    pangrams: pangrams.filter((w) => !found.has(w)).length,
    perfect: pangrams.filter((w) => w.length === 7 && !found.has(w)).length,
    firsts, lens, grid,
    two: Object.keys(two).sort().map((k) => [k, two[k]]),
  };
}

/** Fisher-Yates over the six outer letters (the centre never moves). */
export function shuffled(outer, rand = Math.random) {
  const a = outer.slice();
  for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; }
  return a;
}
